from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")
ws = wb.active

# Extract company data from row 11
company_data = {}
for col in range(2, 9):  # Columns B to G
    company = ws.cell(row=11, column=col).value
    if company:
        company_data[company] = []

# Extract country data from column A (rows 1 to 10)
country_data = {}
for row in range(1, 11):
    country = ws.cell(row=row, column=1).value
    if country:
        country_data[country] = []

# Populate country data with company employee counts
for row in range(1, 11):
    country = ws.cell(row=row, column=1).value
    for col in range(2, 9):
        company = ws.cell(row=11, column=col).value
        if company and country:
            employee_count = ws.cell(row=row, column=col).value
            if employee_count is not None and employee_count > 0:
                country_data[country].append(company)

# Count how many countries each company operates in
company_country_count = {}
for company in company_data:
    count = 0
    for country, companies in country_data.items():
        if company in companies:
            count += 1
    company_country_count[company] = count

# Write the results to I12 and I13
ws.cell(row=12, column=9).value = company_country_count.get("ABC", 0)
ws.cell(row=13, column=9).value = company_country_count.get("EFG", 0)

# Save the workbook
wb.save("output.xlsx")
