from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")
ws_datensatz = wb["Datensatz"]
ws_analyse = wb["Analyse"]

# Define the product range in Datensatz (C4:J33)
product_data = ws_datensatz["C4:J33"]

# Count the number of customers who bought both products
num_customers = 30  # As per the data, there are 30 customers

# Create a matrix to store which products each customer bought
customer_products = []

for row in product_data:
    products = []
    for cell in row:
        if cell.value > 0:
            products.append(True)
        else:
            products.append(False)
    customer_products.append(products)

# Calculate the cross-selling matrix for Analyse
cross_sell_matrix = [[0 for _ in range(8)] for _ in range(8)]

for i in range(8):
    for j in range(8):
        if i == j:
            # Diagonal: count how many times product i was purchased
            count = sum(1 for customer in customer_products if customer[i])
            cross_sell_matrix[i][j] = count / num_customers
        else:
            # Count customers who bought both product i and product j
            count = sum(1 for customer in customer_products if customer[i] and customer[j])
            cross_sell_matrix[i][j] = count / num_customers

# Format the values: keep 9 decimal places, omit trailing 0, no decimal places if value is 1
formatted_matrix = []
for row in cross_sell_matrix:
    formatted_row = []
    for value in row:
        if value == 1:
            formatted_row.append("1")
        else:
            formatted_row.append(f"{value:.9f}".rstrip('0').rstrip('.') if '.' in f"{value:.9f}" else f"{value:.9f}")
    formatted_matrix.append(formatted_row)

# Fill the Analyse sheet with the computed values
for i in range(8):
    for j in range(8):
        ws_analyse.cell(row=5 + i, column=4 + j, value=formatted_matrix[i][j])

# Fill D5:K12 with color code #F2F2F2
for row in ws_analyse.iter_rows(min_row=5, max_row=12, min_col=4, max_col=11):
    for cell in row:
        cell.fill = "F2F2F2"

# Save the workbook
wb.save("output.xlsx")
